import React, { Component } from 'react';
import { AuthContext } from '../../context/AuthContext';
import { useNotifications } from '../../context/NotificationContext';
import styles from './OrderManager.module.css';

// Классовый компонент для управления заказами
class OrderManager extends Component {
    static contextType = AuthContext;

    constructor(props) {
        super(props);
        this.state = {
            orders: [],
            loading: true,
            error: null,
            sortField: 'createdAt',
            sortOrder: 'desc',
            filterStatus: '',
            searchTerm: '',
            expandedOrder: null,
            suppliers: [],
            products: []
        };
    }

    componentDidMount() {
        this.fetchAllData();
    }

    componentDidUpdate(prevProps, prevState) {
        if (prevState.sortField !== this.state.sortField ||
            prevState.sortOrder !== this.state.sortOrder ||
            prevState.filterStatus !== this.state.filterStatus) {
            this.fetchOrders();
        }
    }

    fetchAllData = async () => {
        this.setState({ loading: true, error: null });
        try {
            const [ordersData, suppliersData, productsData] = await Promise.all([
                this.fetchOrdersData(),
                this.fetchSuppliersData(),
                this.fetchProductsData()
            ]);

            this.setState({
                orders: ordersData,
                suppliers: suppliersData,
                products: productsData,
                loading: false
            });
        } catch (error) {
            this.setState({
                error: error.message,
                loading: false
            });
            this.props.showNotification('Ошибка загрузки данных', 'error');
        }
    };

    fetchOrdersData = async () => {
        const { user, token } = this.context;
        const query = new URLSearchParams({
            sortBy: this.state.sortField,
            sortOrder: this.state.sortOrder,
            ...(this.state.filterStatus && { status: this.state.filterStatus })
        }).toString();

        const response = await fetch(`http://localhost:5000/api/orders?${query}`, {
            headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await response.json();

        if (data.success) {
            // Фильтруем заказы по роли пользователя
            if (user.role === 'user') {
                return (data.data.orders || []).filter(order =>
                    order.createdBy?._id === user.id
                );
            }
            return data.data.orders || [];
        } else {
            throw new Error(data.message);
        }
    };

    fetchSuppliersData = async () => {
        const response = await fetch('http://localhost:5000/api/suppliers?limit=100');
        const data = await response.json();
        return data.success ? data.data.suppliers || [] : [];
    };

    fetchProductsData = async () => {
        const response = await fetch('http://localhost:5000/api/products?limit=100');
        const data = await response.json();
        return data.success ? data.data.products || [] : [];
    };

    fetchOrders = async () => {
        try {
            const orders = await this.fetchOrdersData();
            this.setState({ orders });
        } catch (error) {
            this.setState({ error: error.message });
            this.props.showNotification('Ошибка загрузки заказов', 'error');
        }
    };

    // Обработчики событий
    onInventoryUpdate = async (orderId, updates) => {
        try {
            const { token } = this.context;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify(updates)
            });

            const data = await response.json();
            if (data.success) {
                await this.fetchOrders();
                this.props.showNotification('Заказ обновлен успешно', 'success');
                return { success: true, order: data.data.order };
            } else {
                this.props.showNotification(data.message, 'error');
                return { success: false, message: data.message };
            }
        } catch (error) {
            this.props.showNotification('Ошибка обновления заказа', 'error');
            return { success: false, message: error.message };
        }
    };

    onDeleteOrder = async (orderId) => {
        if (!window.confirm('Удалить этот заказ?')) return;

        try {
            const { token } = this.context;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}`, {
                method: 'DELETE',
                headers: { 'Authorization': `Bearer ${token}` }
            });

            const data = await response.json();
            if (data.success) {
                await this.fetchOrders();
                this.props.showNotification('Заказ удален', 'success');
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка удаления', 'error');
        }
    };

    onSupplierRate = async (supplierId, rating) => {
        try {
            const { token } = this.context;
            const response = await fetch(`http://localhost:5000/api/suppliers/${supplierId}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ rating })
            });

            const data = await response.json();
            if (data.success) {
                this.props.showNotification('Рейтинг поставщика обновлен', 'success');
                await this.fetchSuppliersData();
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка обновления рейтинга', 'error');
        }
    };

    onDeliveryTrack = (orderId) => {
        this.props.showNotification(`Отслеживание доставки заказа ${orderId}`, 'info');
    };

    handleSort = (field) => {
        this.setState(prev => ({
            sortField: field,
            sortOrder: prev.sortField === field && prev.sortOrder === 'asc' ? 'desc' : 'asc'
        }));
    };

    handleStatusFilter = (status) => {
        this.setState({ filterStatus: status });
    };

    handleSearch = (e) => {
        this.setState({ searchTerm: e.target.value });
    };

    toggleOrderExpand = (orderId) => {
        this.setState(prev => ({
            expandedOrder: prev.expandedOrder === orderId ? null : orderId
        }));
    };

    handleStatusChange = async (orderId, newStatus) => {
        try {
            const { token } = this.context;
            const response = await fetch(`http://localhost:5000/api/orders/${orderId}/status`, {
                method: 'PATCH',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({ status: newStatus })
            });

            const data = await response.json();
            if (data.success) {
                await this.fetchOrders();
                this.props.showNotification(`Статус заказа изменен на "${newStatus}"`, 'success');
            } else {
                this.props.showNotification(data.message, 'error');
            }
        } catch (error) {
            this.props.showNotification('Ошибка обновления статуса', 'error');
        }
    };

    getStatusColor = (status) => {
        const colors = {
            'created': '#ffb74d',
            'confirmed': '#4fc3f7',
            'processing': '#9575cd',
            'shipped': '#64b5f6',
            'delivered': '#81c784',
            'cancelled': '#e57373'
        };
        return colors[status] || '#757575';
    };

    getStatusText = (status) => {
        const texts = {
            'created': 'Создан',
            'confirmed': 'Подтвержден',
            'processing': 'В обработке',
            'shipped': 'Отправлен',
            'delivered': 'Доставлен',
            'cancelled': 'Отменен'
        };
        return texts[status] || status;
    };

    getSupplierName = (supplierId) => {
        const supplier = this.state.suppliers.find(s => s._id === supplierId);
        return supplier ? supplier.name : 'Неизвестен';
    };

    calculateOrderStats = () => {
        const { orders } = this.state;
        const stats = {
            totalOrders: orders.length,
            totalCost: orders.reduce((sum, o) => sum + o.totalCost, 0),
            totalQuantity: orders.reduce((sum, o) => sum + o.totalQuantity, 0),
            statusCounts: {}
        };

        orders.forEach(order => {
            stats.statusCounts[order.status] = (stats.statusCounts[order.status] || 0) + 1;
        });

        return stats;
    };

    render() {
        const {
            orders,
            loading,
            error,
            sortField,
            sortOrder,
            searchTerm,
            expandedOrder
        } = this.state;

        const filteredOrders = orders.filter(order => {
            if (!searchTerm) return true;
            const searchLower = searchTerm.toLowerCase();
            return (
                order.orderNumber.toLowerCase().includes(searchLower) ||
                this.getSupplierName(order.supplier).toLowerCase().includes(searchLower) ||
                order.notes?.toLowerCase().includes(searchLower)
            );
        });

        const stats = this.calculateOrderStats();

        if (loading) return <div className={styles.loading}>Загрузка заказов...</div>;
        if (error) return <div className={styles.error}>{error}</div>;

        return (
            <div className={styles.orderManager}>
                <div className={styles.header}>
                    <h2>Управление заказами</h2>
                    <div className={styles.stats}>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Всего заказов:</span>
                            <span className={styles.statValue}>{stats.totalOrders}</span>
                        </div>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Общая сумма:</span>
                            <span className={styles.statValue}>{stats.totalCost.toFixed(2)} ₽</span>
                        </div>
                        <div className={styles.statItem}>
                            <span className={styles.statLabel}>Товаров:</span>
                            <span className={styles.statValue}>{stats.totalQuantity} шт.</span>
                        </div>
                    </div>
                </div>

                <div className={styles.controls}>
                    <div className={styles.searchBox}>
                        <input
                            type="text"
                            placeholder="Поиск по номеру заказа или поставщику..."
                            value={searchTerm}
                            onChange={this.handleSearch}
                            className={styles.searchInput}
                        />
                    </div>

                    <div className={styles.filterControls}>
                        <button
                            onClick={() => this.handleSort('createdAt')}
                            className={`${styles.sortBtn} ${sortField === 'createdAt' ? styles.active : ''}`}
                        >
                            Дата {sortField === 'createdAt' && (sortOrder === 'asc' ? '↑' : '↓')}
                        </button>

                        <button
                            onClick={() => this.handleSort('totalCost')}
                            className={`${styles.sortBtn} ${sortField === 'totalCost' ? styles.active : ''}`}
                        >
                            Сумма {sortField === 'totalCost' && (sortOrder === 'asc' ? '↑' : '↓')}
                        </button>

                        <select
                            onChange={(e) => this.handleStatusFilter(e.target.value)}
                            className={styles.statusFilter}
                            value={this.state.filterStatus}
                        >
                            <option value="">Все статусы</option>
                            <option value="created">Создан</option>
                            <option value="confirmed">Подтвержден</option>
                            <option value="processing">В обработке</option>
                            <option value="shipped">Отправлен</option>
                            <option value="delivered">Доставлен</option>
                            <option value="cancelled">Отменен</option>
                        </select>
                    </div>
                </div>

                <div className={styles.ordersList}>
                    {filteredOrders.length === 0 ? (
                        <div className={styles.noResults}>
                            <p>Заказы не найдены</p>
                        </div>
                    ) : (
                        filteredOrders.map(order => (
                            <div key={order._id} className={styles.orderCard}>
                                <div
                                    className={styles.orderHeader}
                                    onClick={() => this.toggleOrderExpand(order._id)}
                                >
                                    <div className={styles.orderInfo}>
                                        <div className={styles.orderNumber}>
                                            <strong>{order.orderNumber}</strong>
                                            <span className={styles.orderDate}>
                                                {new Date(order.createdAt).toLocaleDateString('ru-RU')}
                                            </span>
                                        </div>
                                        <div className={styles.supplierInfo}>
                                            <span className={styles.supplierName}>
                                                Поставщик: {this.getSupplierName(order.supplier)}
                                            </span>
                                            {order.deliveryAddress?.city && (
                                                <span className={styles.supplierCity}>
                                                    {order.deliveryAddress.city}
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    <div className={styles.orderSummary}>
                                        <div className={styles.orderStats}>
                                            <span className={styles.orderQuantity}>
                                                {order.totalQuantity} шт.
                                            </span>
                                            <span className={styles.orderTotal}>
                                                {order.totalCost.toFixed(2)} ₽
                                            </span>
                                        </div>
                                        <div
                                            className={styles.orderStatus}
                                            style={{ backgroundColor: this.getStatusColor(order.status) }}
                                        >
                                            {this.getStatusText(order.status)}
                                        </div>
                                        <div className={styles.expandIcon}>
                                            {expandedOrder === order._id ? '▲' : '▼'}
                                        </div>
                                    </div>
                                </div>

                                {expandedOrder === order._id && (
                                    <div className={styles.orderDetails}>
                                        <div className={styles.purchasesSection}>
                                            <h4>Состав заказа:</h4>
                                            <div className={styles.purchasesList}>
                                                {order.purchases?.map((purchaseId, index) => (
                                                    <div key={index} className={styles.purchaseItem}>
                                                        <div className={styles.purchaseProduct}>
                                                            <strong>Товар #{index + 1}</strong>
                                                            <span>ID: {purchaseId}</span>
                                                        </div>
                                                        <div className={styles.purchaseActions}>
                                                            <button
                                                                onClick={() => this.onDeliveryTrack(order._id)}
                                                                className={styles.trackBtn}
                                                            >
                                                                Отследить
                                                            </button>
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>

                                        <div className={styles.orderMeta}>
                                            <div className={styles.metaItem}>
                                                <strong>Создал:</strong>
                                                <span>{order.createdBy?.username || 'Неизвестно'}</span>
                                            </div>
                                            {order.estimatedDeliveryDate && (
                                                <div className={styles.metaItem}>
                                                    <strong>Ожидаемая доставка:</strong>
                                                    <span>{new Date(order.estimatedDeliveryDate).toLocaleDateString('ru-RU')}</span>
                                                </div>
                                            )}
                                            {order.deliveryDate && (
                                                <div className={styles.metaItem}>
                                                    <strong>Дата доставки:</strong>
                                                    <span>{new Date(order.deliveryDate).toLocaleDateString('ru-RU')}</span>
                                                </div>
                                            )}
                                            {order.notes && (
                                                <div className={styles.metaItem}>
                                                    <strong>Примечания:</strong>
                                                    <span>{order.notes}</span>
                                                </div>
                                            )}
                                        </div>

                                        <div className={styles.orderActions}>
                                            {order.status !== 'delivered' && order.status !== 'cancelled' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'delivered')}
                                                    className={styles.deliverBtn}
                                                >
                                                    Отметить доставленным
                                                </button>
                                            )}

                                            {order.status !== 'cancelled' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'cancelled')}
                                                    className={styles.cancelBtn}
                                                >
                                                    Отменить заказ
                                                </button>
                                            )}

                                            {order.status === 'created' && (
                                                <button
                                                    onClick={() => this.onDeleteOrder(order._id)}
                                                    className={styles.deleteBtn}
                                                >
                                                    Удалить заказ
                                                </button>
                                            )}

                                            {order.status === 'confirmed' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'processing')}
                                                    className={styles.processBtn}
                                                >
                                                    Начать обработку
                                                </button>
                                            )}

                                            {order.status === 'processing' && (
                                                <button
                                                    onClick={() => this.handleStatusChange(order._id, 'shipped')}
                                                    className={styles.shipBtn}
                                                >
                                                    Отправить
                                                </button>
                                            )}

                                            <button
                                                onClick={() => this.onSupplierRate(order.supplier, 5)}
                                                className={styles.rateBtn}
                                            >
                                                Оценить поставщика
                                            </button>
                                        </div>
                                    </div>
                                )}
                            </div>
                        ))
                    )}
                </div>
            </div>
        );
    }
}

// Обертка для использования хуков
function OrderManagerWrapper() {
    const { user } = React.useContext(AuthContext);
    const { showSuccess, showError, showInfo } = useNotifications();

    const showNotification = (message, type) => {
        if (type === 'success') showSuccess(message);
        else if (type === 'error') showError(message);
        else if (type === 'warning') showInfo(message);
        else showInfo(message);
    };

    if (!user) {
        return (
            <div className={styles.accessDenied}>
                <h2>Доступ запрещен</h2>
                <p>Для просмотра заказов необходимо войти в систему</p>
            </div>
        );
    }

    return <OrderManager showNotification={showNotification} />;
}

export default OrderManagerWrapper;
